import re
import sys

values = {}
pattern = re.compile(
    r"(\w+)\s*<-\s*(?:(\d+)|\(\s*(\w+)\s*([+-])\s*(\d+)\s*\)\s*mod\s*(\d+))\s*;?"
)

for line in sys.stdin:
    match = pattern.fullmatch(line.strip())
    if not match:
        continue

    target, literal, source, operator, amount, modulus = match.groups()
    if literal is not None:
        values[target] = int(literal)
    else:
        change = int(amount)
        if operator == "-":
            change = -change
        values[target] = (values[source] + change) % int(modulus)

print(
    f"a ?= {values['a']}; b ?= {values['b']}; c ?= {values['c']}; "
    f"d ?= {values['d']}; TMP ?= {values['TMP']};"
)
